def drive(me, enemy, arena):
    eh = radians(enemy.heading)
    ex = cos(eh)
    ey = sin(eh)
    ux = me.x - enemy.x
    uy = me.y - enemy.y
    d = hypot(ux, uy)
    if d < 0.01:
        d = 0.01
    dot = (ux * ex + uy * ey) / d
    b_enemy = bearing_to(enemy.x, enemy.y)
    desired = b_enemy

    if d < 1.5:
        desired = b_enemy
    elif dot > 0.2 and d < 4.0:
        cross = ex * uy - ey * ux
        if cross >= 0:
            tx = enemy.x - ey * 2.5
            ty = enemy.y + ex * 2.5
        else:
            tx = enemy.x + ey * 2.5
            ty = enemy.y - ex * 2.5
        desired = bearing_to(tx, ty)
    elif dot < -0.3 and d < 3.0:
        desired = b_enemy
    else:
        tx = enemy.x - ex * 1.5
        ty = enemy.y - ey * 1.5
        r = hypot(tx, ty)
        max_r = arena.radius - 1.0
        if r > max_r:
            tx = tx / r * max_r
            ty = ty / r * max_r
        desired = bearing_to(tx, ty)

    r2 = me.x * me.x + me.y * me.y
    if r2 > (arena.radius - 1.2) ** 2:
        desired = bearing_to(0, 0)

    err = desired - me.heading
    while err > 180:
        err -= 360
    while err < -180:
        err += 360

    if err > 20:
        return (-0.8, 0.8)
    elif err < -20:
        return (0.8, -0.8)
    else:
        if err > 5:
            return (0.8, 1.0)
        elif err < -5:
            return (1.0, 0.8)
        return (1.0, 1.0)

